public void modifiedField(FieldId _fieldId)
{
    next modifiedField(_fieldId);

    switch(_fieldId)
    {
        case fieldNum(SalesTable, RRBBookTable):
            this.RRBUpdateBookSalesLine();
            break;
    }
}

public void RRBUpdateBookSalesLine()
{
    SalesLine salesLine;

    while select forupdate salesLine
                where salesLine.SalesId == this.SalesId
    {
        salesLine.RRBBookTable = this.RRBBookTable;
        ttsbegin;
        if(salesLine.validateWrite())
        {
            salesLine.update();
        }
        ttscommit;
    }

    this.RRBReseachIfNeeded();

}

public void RRBReseachIfNeeded()
{
    FormDataSource formDataSource = FormDataUtil::getFormDataSource(this);

    if(formDataSource)
    {
        formDataSource.research(true);
    }
}

public Common RRBFantasyBookLookup(FormReferenceControl _formReferenceControl)
{
    SysReferenceTableLookup refTableLookup = SysReferenceTableLookup::newParameters(tableNum(RRBBookTable), _formReferenceControl);

    refTableLookup.parmQuery(this.RRBGetFantasyBookLookupQuery());
    refTableLookup.addLookupfield(fieldNum(RRBBookTable, Id));
    refTableLookup.addLookupfield(fieldNum(RRBBookTable, Name));
    refTableLookup.addLookupfield(fieldNum(RRBBookTable, Genre));
    refTableLookup.addLookupfield(fieldNum(RRBBookTable, Author));

    return refTableLookup.performFormLookup();
}
